import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { loginUser } from '../services/api';
import { useAuth } from '../context/AuthContext';
import '../styles/login.css';

export default function LoginPage() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const { login, user } = useAuth();
  const navigate = useNavigate();

  React.useEffect(() => {
    if (user) navigate(user.role === 'ADMIN' ? '/admin' : '/portal', { replace: true });
  }, [user, navigate]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!email || !password) { setError('Please enter your email and password.'); return; }
    setLoading(true);
    try {
      const res = await loginUser(email, password);
      const userData = res.data;
      login(userData);
      if (userData.role === 'ADMIN') navigate('/admin', { replace: true });
      else navigate('/portal', { replace: true });
    } catch (err) {
      const msg = err.response?.data?.message || err.response?.data || 'Invalid credentials. Please try again.';
      setError(typeof msg === 'string' ? msg : 'Login failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const seats = Array.from({ length: 30 });

  return (
    <div className="login-page">
      {/* Left Hero */}
      <div className="login-hero">
        <div className="hero-logo">
          <div className="hero-logo-icon">🎭</div>
          <div className="hero-logo-text">SeatSync</div>
        </div>
        <h1 className="hero-title">
          Every Great<br />Experience<br />Starts With a <span>Seat.</span>
        </h1>
        <p className="hero-subtitle">
          Book movies, concerts, and live events effortlessly.
          Choose your perfect seat, lock it instantly, and enjoy the show.
        </p>
        <div className="hero-features">
          {['Real-time seat availability', 'Instant booking confirmation', 'Secure payments', 'Easy cancellations'].map(f => (
            <div className="hero-feature" key={f}>
              <div className="hero-feature-dot" />
              <span>{f}</span>
            </div>
          ))}
        </div>
        <div className="hero-seats">
          {seats.map((_, i) => <div key={i} className="hero-seat-dot" />)}
        </div>
      </div>

      {/* Right Form */}
      <div className="login-form-panel">
        <div className="login-form-inner">
          <h2>Welcome back</h2>
          <p className="login-tagline">Sign in to your account to continue</p>

          {error && <div className="alert alert-error">{error}</div>}

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="email">Email Address</label>
              <input
                id="email"
                type="email"
                className="form-control"
                placeholder="you@example.com"
                value={email}
                onChange={e => setEmail(e.target.value)}
                autoComplete="email"
              />
            </div>

            <div className="form-group">
              <label htmlFor="password">Password</label>
              <input
                id="password"
                type="password"
                className="form-control"
                placeholder="••••••••"
                value={password}
                onChange={e => setPassword(e.target.value)}
                autoComplete="current-password"
              />
              {/* ── Forgot Password Link ── */}
              <div style={{ textAlign: 'right', marginTop: 6 }}>
                <Link
                  to="/forgot-password"
                  style={{ fontSize: 12, color: 'var(--text-secondary)' }}
                >
                  Forgot password?
                </Link>
              </div>
            </div>

            <button
              type="submit"
              className="btn btn-primary login-submit"
              disabled={loading}
            >
              {loading ? 'Signing in...' : 'Sign In'}
            </button>
          </form>

          <div className="login-divider"><span>or</span></div>

          <p className="login-footer">
            Don't have an account?{' '}
            <Link to="/register">Create one</Link>
          </p>

          <div style={{ marginTop: 32, padding: '16px', borderRadius: 8, background: 'rgba(212,175,55,0.05)', border: '1px solid rgba(212,175,55,0.15)' }}>
            <p style={{ fontSize: 12, color: 'var(--text-secondary)', marginBottom: 8, fontWeight: 600, letterSpacing: '0.5px', textTransform: 'uppercase' }}>Access Portals</p>
            <p style={{ fontSize: 13, color: 'var(--text-muted)' }}>
              <strong style={{ color: 'var(--gold)' }}>Admin</strong> — Manage shows, venues & schedules<br />
              <strong style={{ color: 'var(--teal)' }}>User</strong> — Browse & book your seats
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}
